/* RAMIR1 -> typed FLAT1, with shape and operation validation. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <errno.h>
static void bad(int line,const char *msg){fprintf(stderr,"FLAT line %d: %s\n",line,msg);exit(2);}
static int number(const char *s,int line){if(!s)bad(line,"missing dimension");char *end;errno=0;long v=strtol(s,&end,10);if(errno||*end||v<1||v>64)bad(line,"dimension outside 1..64");return (int)v;}
static double finite(const char *s,int line){if(!s)bad(line,"missing value");char *end;errno=0;double v=strtod(s,&end);if(errno||end==s||*end||!isfinite(v))bad(line,"nonfinite or malformed number");return v;}
int main(int argc,char **argv){if(argc!=3){fputs("usage: flat_check input.ir output.flat\n",stderr);return 2;}FILE *in=fopen(argv[1],"r"),*out=fopen(argv[2],"w");if(!in||!out){perror("open");return 2;}char line[131072];if(!fgets(line,sizeof line,in)||strcmp(line,"RAMIR1\n"))bad(1,"bad header");fputs("FLAT1\n",out);int ln=1,ops=0;while(fgets(line,sizeof line,in)){ln++;char *tok[9000];int n=0;for(char *s=strtok(line," \t\r\n");s;s=strtok(NULL," \t\r\n")){if(n==9000)bad(ln,"too many tokens");tok[n++]=s;}if(!n)continue;int p=1,rank=0,d[2]={1,1},operands=0;const char *op=tok[0];if(!strcmp(op,"VECTOR")){int mode=(int)finite(p<n?tok[p++]:NULL,ln);if(mode<0||mode>3)bad(ln,"bad vector mode");rank=1;d[0]=number(p<n?tok[p++]:NULL,ln);operands=2*d[0];}else if(!strcmp(op,"MATMUL")){int m=number(p<n?tok[p++]:NULL,ln),k=number(p<n?tok[p++]:NULL,ln),c=number(p<n?tok[p++]:NULL,ln);rank=2;d[0]=m;d[1]=c;operands=m*k+k*c;}else if(!strcmp(op,"TRANSPOSE")){int m=number(p<n?tok[p++]:NULL,ln),c=number(p<n?tok[p++]:NULL,ln);rank=2;d[0]=c;d[1]=m;operands=m*c;}else if(!strcmp(op,"AFFINE")){rank=0;operands=4;}else if(!strcmp(op,"ROTATE")||!strcmp(op,"TRANSLATE")){int count=number(p<n?tok[p++]:NULL,ln);rank=2;d[0]=count;d[1]=3;operands=(!strcmp(op,"ROTATE")?1:3)+count*3;}else bad(ln,"unknown operation");if(n-p<operands)bad(ln,"truncated operands");for(int i=0;i<operands;i++)finite(tok[p++],ln);int output_count=rank==0?1:rank==1?d[0]:d[0]*d[1];int asserted=0;if(p<n){if(strcmp(tok[p++],"ASSERT"))bad(ln,"invalid suffix");if(n-p!=output_count)bad(ln,"assertion shape mismatch");for(;p<n;p++)finite(tok[p],ln);asserted=1;}fprintf(out,"OP %d %s F64 RANK %d",ops,op,rank);for(int i=0;i<rank;i++)fprintf(out," %d",d[i]);fprintf(out," ELEMENTS %d ASSERT %d\n",output_count,asserted);ops++;}if(!ops)bad(ln,"empty program");fclose(in);if(fclose(out))return 2;return 0;}
